package contentextractor

import (
	"bytes"
	"context"
	"os"
	"strings"
	"testing"

	"github.com/damorris25/content-extractor/metadata"
)

// Accuracy tests validate extraction results against known expected content
// from the rich test fixtures. These fixtures are generated by
// scripts/gen-test-rich.go with deterministic, known content.

func TestAccuracy_RichDOCX(t *testing.T) {
	data, err := os.ReadFile("../testdata/rich.docx")
	if err != nil {
		t.Fatalf("failed to read test file: %v", err)
	}
	result, err := Extract(context.Background(), bytes.NewReader(data), "")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	// Verify all paragraphs are extracted.
	expectedPhrases := []string{
		"Quarterly Financial Report - Q4 2025",
		"Prepared by the Finance Department",
		"Revenue for Q4 reached $4.2 million",
		"15% increase over Q3",
		"Operating expenses were $3.1 million",
		"operating margin of 26.2%",
		"enterprise segment grew 22% year-over-year",
		"healthcare and financial services",
		"Customer retention rate improved to 94.3%",
		"R&D investment totaled $890,000",
		"next-generation platform capabilities",
	}
	for _, phrase := range expectedPhrases {
		if !strings.Contains(result.Text, phrase) {
			t.Errorf("missing phrase %q in extracted text", phrase)
		}
	}

	// Verify metadata.
	metaTests := []struct {
		key  string
		want string
	}{
		{metadata.KeyTitle, "Quarterly Financial Report"},
		{metadata.KeyCreator, "Jane Smith"},
		{metadata.KeySubject, "Finance, Q4 2025, Revenue Analysis"},
		{metadata.KeyDescription, "Comprehensive quarterly financial analysis with revenue breakdown and projections."},
	}
	for _, tt := range metaTests {
		if got := result.Metadata.Get(tt.key); got != tt.want {
			t.Errorf("Metadata[%q] = %q, want %q", tt.key, got, tt.want)
		}
	}
}

func TestAccuracy_UnicodeDOCX(t *testing.T) {
	data, err := os.ReadFile("../testdata/unicode.docx")
	if err != nil {
		t.Fatalf("failed to read test file: %v", err)
	}
	result, err := Extract(context.Background(), bytes.NewReader(data), "")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	expectedPhrases := []string{
		"The quick brown fox jumps over the lazy dog",
		"\u6771\u4EAC\u306F\u65E5\u672C\u306E\u9996\u90FD\u3067\u3059",           // Japanese
		"\u4E2D\u6587\u6D4B\u8BD5\u6587\u672C",                                     // Chinese
		"\uD55C\uAD6D\uC5B4",                                                       // Korean
		"\u00A9\u00AE\u2122",                                                        // Symbols
	}
	for _, phrase := range expectedPhrases {
		if !strings.Contains(result.Text, phrase) {
			t.Errorf("missing phrase %q in extracted text", phrase)
		}
	}
}

func TestAccuracy_RichXLSX(t *testing.T) {
	data, err := os.ReadFile("../testdata/rich.xlsx")
	if err != nil {
		t.Fatalf("failed to read test file: %v", err)
	}
	result, err := Extract(context.Background(), bytes.NewReader(data), "")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	// Verify header and data cells are extracted.
	expectedValues := []string{
		"Employee", "Department", "Salary",
		"Alice Chen", "Engineering", "125000",
		"Bob Martinez", "Marketing", "98000",
		"Carol Tanaka", "Sales", "105000",
	}
	for _, val := range expectedValues {
		if !strings.Contains(result.Text, val) {
			t.Errorf("missing value %q in extracted text", val)
		}
	}

	if got := result.Metadata.Get(metadata.KeyTitle); got != "Employee Compensation Data" {
		t.Errorf("Title = %q, want %q", got, "Employee Compensation Data")
	}
}

