func TestAccuracy_RichDXF(t *testing.T) {
	data, err := os.ReadFile("../testdata/rich.dxf")
	if err != nil {
		t.Fatalf("failed to read test file: %v", err)
	}
	result, err := Extract(context.Background(), bytes.NewReader(data), "image/vnd.dxf")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	expectedTexts := []string{
		"Building A - Ground Floor Plan",
		"Scale: 1:100",
		"North Elevation",
		"Load-bearing wall",
		"Thickness: 300mm",
		"Reinforced concrete",
		"Fire Exit - Do Not Block",
		"Electrical Panel EP-01",
		"15.750m",
		"8.200m",
		"WindowType-A",
		"DoorType-B",
		"Stairwell Access",
	}
	for _, text := range expectedTexts {
		if !strings.Contains(result.Text, text) {
			t.Errorf("missing text %q in extracted content", text)
		}
	}

	// Verify metadata.
	if got := result.Metadata.Get("cad:version"); got != "AC1032" {
		t.Errorf("version = %q, want AC1032", got)
	}
	if got := result.Metadata.Get("cad:units"); got != "Meters" {
		t.Errorf("units = %q, want Meters", got)
	}

	// Verify all layers extracted.
	layers := result.Metadata.Get("cad:layers")
	for _, layer := range []string{"Foundation", "Structural", "Electrical", "Plumbing", "HVAC"} {
		if !strings.Contains(layers, layer) {
			t.Errorf("missing layer %q in %q", layer, layers)
		}
	}
}

func TestAccuracy_RichMP3(t *testing.T) {
	data, err := os.ReadFile("../testdata/rich.mp3")
	if err != nil {
		t.Fatalf("failed to read test file: %v", err)
	}
	result, err := Extract(context.Background(), bytes.NewReader(data), "audio/mpeg")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	metaTests := []struct {
		key  string
		want string
	}{
		{metadata.KeyTitle, "Midnight in the Garden of Sound"},
		{metadata.KeyCreator, "The Electronica Collective"},
		{"audio:album", "Synthetic Dreams Vol. 3"},
		{"audio:track", "7/12"},
		{"audio:genre", "Electronic"},
		{"audio:album-artist", "Various Artists"},
	}
	for _, tt := range metaTests {
		if got := result.Metadata.Get(tt.key); got != tt.want {
			t.Errorf("Metadata[%q] = %q, want %q", tt.key, got, tt.want)
		}
	}

	// Text summary should contain title and artist.
	if !strings.Contains(result.Text, "Midnight in the Garden of Sound") {
		t.Errorf("text summary missing title")
	}
	if !strings.Contains(result.Text, "The Electronica Collective") {
		t.Errorf("text summary missing artist")
	}
}
